// Single runnable file with multiple top-level package-private classes.
package com.bank.anonthis;

import java.util.*;
import java.util.logging.*;

public class ThisScopeDemo {
    private static final Logger log = Logger.getLogger(ThisScopeDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Registry registry = new Registry();
        NotificationService service = new NotificationService("EMAIL", registry);
        service.scheduleAlert("Rajesh", "Transfer of Rs.50000 completed");
        service.scheduleWithLambda("Priya", "Account statement ready");
        log.info(() -> "Registry now holds: " + registry.describe());
    }
}

// ─── Would be in service/NotificationService.java ───
class NotificationService {
    private static final Logger log = Logger.getLogger(NotificationService.class.getName());
    private final String channel;          // OUTER field
    private final Registry registry;

    NotificationService(String channel, Registry registry) {
        this.channel = channel; this.registry = registry;
    }

    String status() { return "NotificationService(" + channel + ")"; }

    void scheduleAlert(String customer, String message) {
        // Anonymous Runnable with its OWN field `channel` that SHADOWS the outer one.
        Runnable task = new Runnable() {
            private final String channel = "INLINE";  // shadows NotificationService.channel

            @Override public void run() {
                // this.channel  → the anonymous object's field = "INLINE"
                log.info(() -> "this.channel (anon) = " + this.channel);
                // NotificationService.this.channel → outer field = "EMAIL"
                log.info(() -> "NotificationService.this.channel (outer) = "
                        + NotificationService.this.channel);
                // this.toString → anonymous instance ; qualified this.status → outer method
                log.info(() -> "this (anon) class = " + this.getClass().getSimpleName());
                log.info(() -> "outer status = " + NotificationService.this.status());
                // Register BOTH the task (this) and the enclosing service (Outer.this)
                registry.add("task:" + this.getClass().getName());
                registry.add("service:" + NotificationService.this.status());
                log.info(() -> "Alert to " + customer + ": " + message
                        + " via " + NotificationService.this.channel);
            }
        };
        task.run();
    }

    void scheduleWithLambda(String customer, String message) {
        // In a LAMBDA, `this` means the enclosing NotificationService — NOT a lambda object.
        Runnable task = () -> {
            log.info(() -> "LAMBDA this.channel = " + this.channel);  // = "EMAIL" (outer)
            log.info(() -> "LAMBDA this.status = " + this.status());  // outer method
            log.info(() -> "Alert to " + customer + ": " + message + " via " + this.channel);
        };
        task.run();
    }
}

// ─── Would be in registry/Registry.java ───
class Registry {
    private final List<String> entries = new ArrayList<>();
    void add(String entry) { entries.add(entry); }
    String describe() { return entries.toString(); }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
